62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
74	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
75	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
79	
80	    /**
81	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
82	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    /**
120	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
121	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
122	     */
123	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
124	        List<String> missing = new ArrayList<>();
125	        if (isBlank(ownerFieldsDto.getFirstName())) {
126	            missing.add("firstName");
127	        }
128	        if (isBlank(ownerFieldsDto.getLastName())) {
129	            missing.add("lastName");
130	        }
131	        if (isBlank(ownerFieldsDto.getAddress())) {
132	            missing.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missing.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missing.add("telephone");
139	        }
140	        if (!missing.isEmpty()) {
141	            throw new RequiredFieldsMissingException(missing);
142	        }
143	    }
144	
145	    private static boolean isBlank(String value) {
146	        return value == null || value.isBlank();
147	    }
148	
149	    /**
150	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
151	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
152	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
153	     * normalized value is what gets stored, returned and used for every address comparison; a value
154	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
155	     * rejects it.
156	     *
157	     * @param address the raw address as supplied by the caller, may be {@code null}
158	     * @return the normalized address ({@code ""} when blank or {@code null})
159	     */
160	    private static String normalizeAddress(String address) {
161	        if (address == null) {
162	            return "";
163	        }
164	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
165	        if (collapsed.isEmpty()) {
166	            return "";
167	        }
168	        String[] tokens = collapsed.split(" ");
169	        StringBuilder sb = new StringBuilder(collapsed.length());
170	        for (int i = 0; i < tokens.length; i++) {
171	            String token = tokens[i];
172	            switch (token) {
173	                case "ST" -> token = "STREET";
174	                case "RD" -> token = "ROAD";
175	                case "AVE" -> token = "AVENUE";
176	                default -> { }
177	            }
178	            if (i > 0) {
179	                sb.append(' ');
180	            }
181	            sb.append(token);
182	        }
183	        return sb.toString();
184	    }
185	
186	    /**
187	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
188	     * A leading {@code +} and its country code are kept as given; otherwise the country code
189	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
190	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
191	     * is recognized the national number must have the exact length that code requires ({@code +61}
192	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
193	     * returned.
194	     *
195	     * @param telephone the raw telephone as supplied by the caller
196	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
197	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
198	     *     national-number length is wrong for its country code
199	     */
200	    private static String normalizeTelephone(String telephone) {
201	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
202	        String e164;
203	        if (cleaned.startsWith("+")) {
204	            e164 = "+" + cleaned.substring(1);
205	        } else {
206	            String national = cleaned;
207	            if (national.startsWith("0")) {
208	                national = national.substring(1);
209	            }
210	            e164 = "+61" + national;
211	        }
212	        String digits = e164.substring(1);
213	        if (!digits.matches("\\d{8,15}")) {
214	            throw new InvalidTelephoneException(
215	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
216	        }
217	        if (digits.startsWith("61")) {
218	            requireNationalLength(digits.substring(2), 9, "+61");
219	        } else if (digits.startsWith("1")) {
220	            requireNationalLength(digits.substring(1), 10, "+1");
221	        }
222	        return e164;
223	    }
224	
225	    /**
226	     * Enforces that the national portion of an E.164 number has the exact number of digits its
227	     * country code requires.
228	     *
229	     * @param national the national-number digits (the part after the country code)
230	     * @param expected the exact national-number length the country code requires
231	     * @param countryCode the country code, for the error message
232	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
233	     */
234	    private static void requireNationalLength(String national, int expected, String countryCode) {
235	        if (national.length() != expected) {
236	            throw new InvalidTelephoneException(
237	                "Telephone with country code '" + countryCode + "' must have " + expected
238	                    + " national digits");
239	        }
240	    }
241	
242	    /**
243	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
244	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
245	     *
246	     * @param email the raw email as supplied by the caller, may be {@code null}
247	     * @return the lower-cased email, or {@code null} when none was supplied
248	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
249	     */
250	    private static String normalizeEmail(String email) {
251	        if (email == null || email.isBlank()) {
252	            return null;
253	        }
254	        String trimmed = email.trim();
255	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
256	            throw new InvalidEmailException("Email must be a syntactically valid address");
257	        }
258	        return trimmed.toLowerCase(Locale.ROOT);
259	    }
260	
261	    /**
262	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
263	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
264	     * householdId}, where the email segment is the empty string when the owner has no email. Because
265	     * the telephone is part of the key, two owners that differ in any one segment (for example two
266	     * members of the same household with different telephones) produce different keys.
267	     *
268	     * @param normalizedTelephone the E.164 telephone of the owner
269	     * @param email the lower-cased email of the owner, may be {@code null}
270	     * @param householdId the stable household identifier of the owner, may be {@code null}
271	     * @return the derived identity key
272	     */
273	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
274	        return (normalizedTelephone == null ? "" : normalizedTelephone)
275	            + "|" + (email == null ? "" : email)
276	            + "|" + (householdId == null ? "" : householdId);
277	    }
278	
279	    /**
280	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
281	     * owner. This one check replaces the former separate telephone, email and household duplicate
282	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
283	     * segment are both allowed. Each existing owner's key is derived from its stored, already
284	     * normalized telephone, email and household identifier.
285	     *
286	     * @param identityKey the derived identity key of the owner being created
287	     * @throws DuplicateIdentityException if another owner already has this identity key
288	     */
289	    private void rejectDuplicateIdentity(String identityKey) {
290	        boolean inUse = this.clinicService.findAllOwners().stream()
291	            .anyMatch(existing -> identityKey.equals(
292	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
293	        if (inUse) {
294	            throw new DuplicateIdentityException(
295	                "An owner with the same identity key already exists");
296	        }
297	    }
298	
299	    /**
300	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
301	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
302	     *
303	     * @param value the raw value, may be {@code null}
304	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
305	     */
306	    private static String normalizeForHousehold(String value) {
307	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
308	    }
309	
310	    /**
311	     * Derives the stable household identifier for an owner from the normalized last name and address.
312	     * The value is a deterministic function of those two fields (compared case-insensitively with
313	     * collapsed whitespace), so every owner in the same
314	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
315	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
316	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
317	     * normalized fields.
318	     *
319	     * @param lastName the last name of the owner being created
320	     * @param address the address of the owner being created
321	     * @return the stable household identifier
322	     */
323	    private static String householdId(String lastName, String address) {
324	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
325	        try {
326	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
327	            StringBuilder sb = new StringBuilder(digest.length * 2);
328	            for (byte b : digest) {
329	                sb.append(String.format("%02x", b));
330	            }
331	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
332	        } catch (NoSuchAlgorithmException e) {
333	            throw new IllegalStateException("SHA-256 not available", e);
334	        }
335	    }
336	
337	    /**
338	     * The maximum number of owners a single city may contain. A create whose city already holds this
339	     * many owners is rejected, so a city never grows beyond this capacity.
340	     */
341	    private static final int CITY_CAPACITY = 50;
342	
343	    /**
344	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
345	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
346	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
347	     * state before the new owner is persisted, so it excludes the owner being created.
348	     *
349	     * @param city the city of the owner being created
350	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
351	     */
352	    private void rejectCityAtCapacity(String city) {
353	        String normalizedCity = normalizeName(city);
354	        long ownersInCity = this.clinicService.findAllOwners().stream()
355	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
356	            .count();
357	        if (ownersInCity >= CITY_CAPACITY) {
358	            throw new CityAtCapacityException(
359	                "The city already contains the maximum number of owners");
360	        }
361	    }
362	
363	    /**
364	     * The maximum number of owners that may be created on a single day. A create made once this many
365	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
366	     * owners are registered per day.
367	     */
368	    private static final int DAILY_OWNER_LIMIT = 100;
369	
370	    /**
371	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
372	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
373	     * rolled forward) registration date of the owner being created. The count reflects the state
374	     * before the new owner is persisted, so it excludes the owner being created.
375	     *
376	     * @param registrationDate the effective business-day registration date of the owner being created
377	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
378	     */
379	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
380	        long ownersToday = this.clinicService.findAllOwners().stream()
381	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
382	            .count();
383	        if (ownersToday >= DAILY_OWNER_LIMIT) {
384	            throw new DailyOwnerLimitExceededException(
385	                "The maximum number of owners for today has already been reached");
386	        }
387	    }
388	
389	    /**
390	     * The number of owners that may already exist for a business day before a create is flagged with
391	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
392	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
393	     */
394	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
395	
396	    /**
397	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
398	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
399	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
400	     * date of the owner being created. The count reflects the state before the new owner is persisted,
401	     * so it excludes the owner being created.
402	     *
403	     * @param registrationDate the effective business-day registration date of the owner being created
404	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
405	     */
406	    private boolean bulkSignupWarning(LocalDate registrationDate) {
407	        long ownersToday = this.clinicService.findAllOwners().stream()
408	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
409	            .count();
410	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
411	    }
412	
413	    /**
414	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
415	     * following Monday, any weekday is returned unchanged.
416	     *
417	     * @param date the effective registration date, supplied or defaulted to the server date
418	     * @return the same date when it is a weekday, otherwise the next Monday
419	     */
420	    private static LocalDate toBusinessDay(LocalDate date) {
421	        DayOfWeek dayOfWeek = date.getDayOfWeek();
422	        if (dayOfWeek == DayOfWeek.SATURDAY) {
423	            return date.plusDays(2);
424	        }
425	        if (dayOfWeek == DayOfWeek.SUNDAY) {
426	            return date.plusDays(1);
427	        }
428	        return date;
429	    }
430	
431	    /**
432	     * Builds the customer code assigned to an owner on create, formatted
433	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
434	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
435	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
436	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
437	     *
438	     * @param city the city of the owner being created
439	     * @param lastName the last name of the owner being created
440	     * @return the formatted customer code
441	     */
442	    private String nextCustomerCode(String city, String lastName) {
443	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
444	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
445	        String normalizedCity = normalizeName(city);
446	        int sequence = (int) this.clinicService.findAllOwners().stream()
447	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
448	            .count() + 1;
449	        return String.format("%s-%s-%04d", city3, last3, sequence);
450	    }
451	
452	    /**
453	     * Counts the existing owners that share the owner-to-be's first and last name, compared
454	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
455	     * new owner is persisted, so it excludes the owner being created.
456	     *
457	     * @param firstName the first name of the owner being created
458	     * @param lastName the last name of the owner being created
459	     * @return the number of existing owners with the same first and last name
460	     */
461	    private int countNamesakes(String firstName, String lastName) {
462	        String normalizedFirstName = normalizeName(firstName);
463	        String normalizedLastName = normalizeName(lastName);
464	        return (int) this.clinicService.findAllOwners().stream()
465	            .filter(existing ->
466	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
467	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
468	            .count();
469	    }
470	
471	    /**
472	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
473	     * number of existing owners already carrying the same {@code householdId}. A household identifier
474	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
475	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
476	     * count includes the owner being created (hence the {@code + 1}).
477	     *
478	     * @param householdId the stable household identifier of the owner being created, or {@code null}
479	     *     when the owner does not share a household
480	     * @return the number of household members after this create (always at least 1)
481	     */
482	    private int householdSize(String householdId) {
483	        if (householdId == null) {
484	            return 1;
485	        }
486	        return (int) this.clinicService.findAllOwners().stream()
487	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
488	            .count() + 1;
489	    }
490	
491	    /**
492	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
493	     * lower-casing.
494	     *
495	     * @param value the raw name, may be {@code null}
496	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
497	     */
498	    private static String normalizeName(String value) {
499	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
500	    }
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner == null) {
507	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	        }
509	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
510	    }
511	
512	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
513	    @Override
514	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
515	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
516	        validateRequiredFields(ownerFieldsDto);
517	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
518	        if (registrationDate == null) {
519	            registrationDate = LocalDate.now();
520	        }
521	        registrationDate = toBusinessDay(registrationDate);
522	        ownerFieldsDto.setRegistrationDate(registrationDate);
523	        rejectDailyOwnerLimit(registrationDate);
524	        rejectCityAtCapacity(ownerFieldsDto.getCity());
525	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
526	        ownerFieldsDto.setTelephone(normalizedTelephone);
527	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
528	        ownerFieldsDto.setEmail(normalizedEmail);
529	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
530	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
531	            : null;
532	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
533	        HttpHeaders headers = new HttpHeaders();
534	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
535	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
536	        owner.setHouseholdId(ownerHouseholdId);
537	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
538	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
539	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
540	        this.clinicService.saveOwner(owner);
541	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
542	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
543	            ownerMapper.membershipLevel(owner));
544	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
545	        headers.setLocation(UriComponentsBuilder.newInstance()
546	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
547	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
548	    }
549	
550	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
551	    @Override
552	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
553	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
554	        if (currentOwner == null) {
555	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
556	        }
557	        currentOwner.setAddress(ownerFieldsDto.getAddress());
558	        currentOwner.setCity(ownerFieldsDto.getCity());
559	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
560	        currentOwner.setLastName(ownerFieldsDto.getLastName());
561	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
562	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
563	        this.clinicService.saveOwner(currentOwner);
564	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Transactional
569	    @Override
570	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
571	        Owner owner = this.clinicService.findOwnerById(ownerId);
572	        if (owner == null) {
573	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	        }
575	        this.clinicService.deleteOwner(owner);
576	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Override
581	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
582	        Owner owner = this.clinicService.findOwnerById(ownerId);
583	        if (owner == null) {
584	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	        }
586	        HttpHeaders headers = new HttpHeaders();
587	        Pet pet = petMapper.toPet(petFieldsDto);
588	        owner.setId(ownerId);
589	        pet.setOwner(owner);
590	        pet.getType().setName(null);
591	        this.clinicService.savePet(pet);
592	        PetDto petDto = petMapper.toPetDto(pet);
593	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
594	            .buildAndExpand(pet.getId()).toUri());
595	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Override
600	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
601	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
602	        if (currentOwner != null) {
603	            Pet currentPet = this.clinicService.findPetById(petId);
604	            if (currentPet != null) {
605	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
606	                currentPet.setName(petFieldsDto.getName());
607	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
608	                this.clinicService.savePet(currentPet);
609	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
610	            }
611	        }
612	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
618	        HttpHeaders headers = new HttpHeaders();
619	        Visit visit = visitMapper.toVisit(visitFieldsDto);
620	        Pet pet = new Pet();
621	        pet.setId(petId);
622	        visit.setPet(pet);
623	        this.clinicService.saveVisit(visit);
624	        VisitDto visitDto = visitMapper.toVisitDto(visit);
625	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
626	            .buildAndExpand(visit.getId()).toUri());
627	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
628	    }
629	
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
634	        Owner owner = this.clinicService.findOwnerById(ownerId);
635	        if (owner != null) {
636	            Pet pet = owner.getPet(petId);
637	            if (pet != null) {
638	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
639	            }
640	        }
641	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
642	    }
643	}
